import React, { useEffect, useRef, useState, useCallback } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const PRELOAD_VIDEO_SRC = "data:video/mp4;base64,";

interface PreloadPageProps {
  onComplete?: () => void;
  targetPath?: string;
}

export const PreloadPage: React.FC<PreloadPageProps> = ({ onComplete, targetPath }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const videoRef = useRef<HTMLVideoElement>(null);
  const [redirected, setRedirected] = useState(false);

  const goToLogin = useCallback(() => {
    if (redirected) return;
    setRedirected(true);

    if (onComplete) {
      onComplete();
      return;
    }

    // Determine target login route
    const current = targetPath || location.pathname;
    if (current.startsWith('/admin')) {
      navigate('/admin/login', { replace: true });
    } else {
      navigate('/login', { replace: true });
    }
  }, [redirected, onComplete, targetPath, location.pathname, navigate]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    video.loop = false;
    video.muted = true;
    video.playsInline = true;

    // Autoplay handler with pointerdown fallback
    const playPromise = video.play();
    if (playPromise !== undefined) {
      playPromise.catch(() => {
        const start = () => {
          if (videoRef.current) {
            videoRef.current.play().catch(() => {});
          }
          document.removeEventListener('pointerdown', start);
          document.removeEventListener('keydown', start);
        };
        document.addEventListener('pointerdown', start, { once: true });
        document.addEventListener('keydown', start, { once: true });
      });
    }

    // Safety fallback timer if video fails or ends
    const fallbackTimer = setTimeout(() => {
      goToLogin();
    }, 8000);

    return () => {
      clearTimeout(fallbackTimer);
    };
  }, [goToLogin]);

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        width: '100vw',
        height: '100dvh',
        minWidth: '100%',
        minHeight: '100%',
        backgroundColor: '#000000',
        zIndex: 999999,
        overflow: 'hidden',
        cursor: 'pointer',
        opacity: redirected ? 0 : 1,
        transition: 'opacity 0.4s ease-in-out',
      }}
      onClick={goToLogin}
    >
      <style>{`
        :root {
          --video-ratio: 16/9;
        }
        .preload-root-animation {
          position: fixed;
          left: 50%;
          top: 50%;
          width: 100vw;
          height: 100dvh;
          margin: 0;
          padding: 0;
          overflow: hidden;
          background: #000;
          transform: translate(-50%, -50%);
          display: block;
        }
        .preload-root-animation video {
          position: absolute;
          left: 50%;
          top: 50%;
          display: block;
          width: auto;
          height: 100%;
          max-width: none;
          max-height: none;
          margin: 0;
          padding: 0;
          object-fit: contain;
          object-position: 50% 50%;
          transform: translate(-50%, -50%);
          transform-origin: center center;
          image-rendering: auto;
          backface-visibility: hidden;
          will-change: transform;
        }
        @media (max-aspect-ratio: 16/9) {
          .preload-root-animation video {
            width: 100vw;
            height: auto;
            min-width: 100vw;
            max-width: 100vw;
            min-height: 0;
            max-height: none;
          }
        }
        @media (min-aspect-ratio: 16/9) {
          .preload-root-animation video {
            height: 100dvh;
            width: auto;
            min-height: 100dvh;
            max-height: 100dvh;
            min-width: 0;
            max-width: none;
          }
        }
        @supports not (height: 100dvh) {
          .preload-root-animation {
            height: 100vh;
          }
          @media (max-aspect-ratio: 16/9) {
            .preload-root-animation video {
              width: 100vw;
            }
          }
          @media (min-aspect-ratio: 16/9) {
            .preload-root-animation video {
              height: 100vh;
            }
          }
        }
      `}</style>

      <main className="preload-root-animation" aria-label="Green Glide animation">
        <video
          ref={videoRef}
          id="greenGlide"
          autoPlay
          muted
          playsInline
          preload="auto"
          onEnded={goToLogin}
        >
          <source src={PRELOAD_VIDEO_SRC} type="video/mp4" />
        </video>
      </main>
    </div>
  );
};

export default PreloadPage;
